func HasTargetWith(preds ...predicate.FileExposure) predicate.FileSubscription {
	return predicate.FileSubscription(func(s *sql.Selector) {
		step := newTargetStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

