// And groups predicates with the AND operator between them.
func And(predicates ...predicate.FileSubscription) predicate.FileSubscription {
	return predicate.FileSubscription(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.FileSubscription) predicate.FileSubscription {
	return predicate.FileSubscription(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.FileSubscription) predicate.FileSubscription {
	return predicate.FileSubscription(sql.NotPredicates(p))
}
